import { createSlice } from '@reduxjs/toolkit';
const initialState = {
    signal_list: {},
    signal_trend_data: undefined,
    signal_history_dict: {},
};
export const signalSlice = createSlice({
    name: 'signal',
    initialState,
    reducers: {
        addSignalItem: (state, action) => {
            state.signal_list[action.payload.signal_uuid] = action.payload;
        },
        removeSignalItem: (state, action) => {
            delete state.signal_list[action.payload];
        },
        setSignalTrendData: (state, action) => {
            state.signal_trend_data = action.payload;
        },
        setSignalHistoryData: (state, action) => {
            state.signal_history_dict[action.payload.signal_uuid] = action.payload.signal_history_list;
        },
        removeSignalHistoryData: (state, action) => {
            delete state.signal_history_dict[action.payload];
        },
        resetSignalSlice() {
            return initialState;
        },
    }
});
export const { actions: signalActions } = signalSlice;
export const { reducer: signalReducer } = signalSlice;
