import { useCallback, useLayoutEffect, useState } from 'react';
import { reducerManager } from '01_app/storeManager';
export function useDynamicApiLoader(apiSlices = [], removeAfterUnmount = true) {
    const [isMountedApi, setIsMountedApi] = useState(false);
    const mountApiLoader = useCallback((apiSlicesInner = []) => {
        if (apiSlicesInner.length === 0) {
            setIsMountedApi(true);
            return;
        }
        apiSlicesInner.forEach((apiSlice) => {
            reducerManager.addMiddleware(apiSlice.middleware);
            reducerManager.add(apiSlice.reducerPath, apiSlice.reducer);
        });
        setIsMountedApi(true);
    }, []);
    const unmountApiLoader = useCallback((apiSlicesInner = []) => {
        if (apiSlicesInner.length === 0)
            return;
        apiSlicesInner.forEach((apiSlice) => {
            reducerManager.removeMiddleware(apiSlice.middleware);
            reducerManager.remove(apiSlice.reducerPath);
        });
        setIsMountedApi(false);
    }, []);
    // useLayoutEffect, а не useEffect: реєстрація й перерендер відбуваються до
    // відмальовки, тож заглушка RTKWrapper не блимає кадром, коли чанк уже
    // завантажений (раніше вона показувалась на кожному монтуванні).
    useLayoutEffect(() => {
        mountApiLoader(apiSlices);
        return () => {
            if (removeAfterUnmount) {
                unmountApiLoader(apiSlices);
            }
        };
        // eslint-disable-next-line
    }, []);
    return { isMountedApi, mountApiLoader, unmountApiLoader };
}
